public class OrderLoadException extends RuntimeException {
    public OrderLoadException(String message, Throwable cause) {
        super(message, cause);                          // giữ exception gốc
    }
}

public Order loadOrder(long id) {
    Optional<Order> order;
    try {
        order = orderDao.findById(id);                  // trả Optional.empty() khi không có
    } catch (SQLException e) {
        throw new OrderLoadException("Không tải được đơn " + id, e);   // map sang 503
    }
    return order.orElseThrow(() -> new OrderNotFoundException("Không tìm thấy đơn " + id));
}
